CREATE TABLE deposits (account_id VARCHAR(64) NOT NULL REFERENCES accounts(id), request_id VARCHAR(64) NOT NULL, payment_hash VARCHAR(64) NOT NULL UNIQUE, payment_request VARCHAR(2048) NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'credited')), created_at DATETIME NOT NULL, credited_at DATETIME, PRIMARY KEY (account_id, request_id));
CREATE TABLE credits (payment_hash VARCHAR(64) PRIMARY KEY REFERENCES deposits(payment_hash), account_id VARCHAR(64) NOT NULL REFERENCES accounts(id), request_id VARCHAR(64) NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), balance_after INTEGER NOT NULL CHECK (balance_after >= 0), created_at DATETIME NOT NULL, FOREIGN KEY (account_id, request_id) REFERENCES deposits(account_id, request_id));
